mapper.update:
UPDATE user_token_usage
SET "inputTokens"  = "inputTokens" + #{input},
    "outputTokens" = "outputTokens" + #{output},
    "totalTokens"  = "totalTokens" + #{total}
WHERE "userId" = #{userId}
  AND "modelName" = #{modelName}
  AND "month" = #{month}

